'use strict';
// Child-only preload: preserve generated bytes and the published loopback rule,
// but prove listener ownership through the exact ChildProcess IPC channel.
require('../live-runner/loopback');
const net = require('node:net');
const nonce = process.env.APIFORGE_PERSISTENT_CHILD_NONCE;
if (!/^[a-f0-9]{64}$/.test(nonce || '') || !process.connected) throw Error('Persistent child channel unavailable');
const listen = net.Server.prototype.listen;
net.Server.prototype.listen = function (...args) {
    let port;
    const notify = event => {
        if (process.connected) process.send({ event, port, nonce }, () => {});
    };
    this.once('listening', () => {
        const address = this.address();
        if (address?.address !== '127.0.0.1' || address.port !== Number(process.env.PORT)) throw Error('Persistent listener refused');
        port = address.port; notify('listening');
    });
    this.once('close', () => notify('closed'));
    return listen.apply(this, args);
};
